// Team-authored package and raster bytes; never generated by another document engine.
import { deflateSync } from "node:zlib";
import { applyDocxOperations, createDocx, exportDocx, openDocx } from "./docx";
import { themedDocxFixture } from "./docx-theme.fixture";
import { zipCrc32 } from "./zip";

function editorialMark(): Uint8Array {
  const encoder = new TextEncoder();
  const chunk = (name: string, bytes: Uint8Array) => {
    const result = new Uint8Array(bytes.length + 12), view = new DataView(result.buffer);
    view.setUint32(0, bytes.length);
    result.set(encoder.encode(name), 4);
    result.set(bytes, 8);
    view.setUint32(bytes.length + 8, zipCrc32(result.subarray(4, bytes.length + 8)));
    return result;
  };
  const header = new Uint8Array(13), view = new DataView(header.buffer);
  view.setUint32(0, 1); view.setUint32(4, 1);
  header[8] = 8; header[9] = 6;
  return new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10, ...chunk("IHDR", header), ...chunk("IDAT", deflateSync(new Uint8Array([0, 51, 102, 153, 255]))), ...chunk("IEND", new Uint8Array())]);
}

/** Synthetic native/PDF QA sample: two explicit pages with supported Word structures. */
export async function printDocxFixture() {
  let document = (await themedDocxFixture()).document;
  document = applyDocxOperations(document, [
    { type: "replace-paragraph", paragraphId: "p0", text: "An editorial document" },
    { type: "replace-paragraph", paragraphId: "p1", text: "Clear writing, thoughtful formatting, and files that remain yours." },
    { type: "format-paragraph", paragraphId: "p0", format: { spacingAfterPoints: 18 } },
    { type: "format-paragraph", paragraphId: "p1", format: { spacingAfterPoints: 18, lineSpacingMultiple: 1.3 } },
    { type: "set-page-layout", layout: { paper: "a4", marginTopPoints: 48, marginRightPoints: 54, marginBottomPoints: 60, marginLeftPoints: 66 } },
  ]);
  const append = (text: string) => {
    document = applyDocxOperations(document, [{ type: "insert-paragraph", text }]);
    return document.paragraphs.at(-1)!.id;
  };
  const first = append("Local files, first");
  document = applyDocxOperations(document, [{ type: "set-list", paragraphId: first, kind: "bullet" }]);
  const second = append("Shared controls, familiar workspace");
  document = applyDocxOperations(document, [{ type: "set-list", paragraphId: second, kind: "numbered" }]);
  const third = append("A deliberate second step");
  document = applyDocxOperations(document, [{ type: "set-list", paragraphId: third, kind: "numbered" }]);
  const link = append("Read the project notes");
  document = applyDocxOperations(document, [
    { type: "set-hyperlink", paragraphId: link, start: 9, end: 22, target: "https://example.com/notes?edition=print&source=markie" },
    { type: "insert-table", afterParagraphId: link, rows: 3, columns: 2, cells: [["Document", "Purpose"], ["Editorial draft", "Write and refine"], ["Local copy", "Keep ownership"]] },
    { type: "insert-image", afterParagraphId: link, bytes: editorialMark(), contentType: "image/png", widthPoints: 24, heightPoints: 24, altText: 'Editorial mark <&> "blue"' },
  ]);
  const continuation = append("First-page closing note.Second-page continuation");
  document = applyDocxOperations(document, [
    { type: "insert-page-break", paragraphId: continuation, offset: 24 },
    { type: "format-paragraph", paragraphId: continuation, format: { spacingBeforePoints: 18, spacingAfterPoints: 12 } },
  ]);
  append("The supported document view is ready to print or save as PDF. Comments stay in the editable file, not on these pages.");
  document = applyDocxOperations(document, [{ type: "add-comment", paragraphId: "p0", author: "Synthetic reviewer", text: "Private review note excluded from printed output." }]);
  const bytes = await exportDocx(document);
  return { document: await openDocx(bytes), bytes };
}

/** Native fragmentation probes: HTML structure alone cannot prove blank pages. */
export async function printBreakDocxFixture(kind: "leading" | "trailing" | "consecutive" | "middle" | "empty") {
  let document = await createDocx(kind === "empty" ? "" : "BeforeAfter");
  const offset = kind === "trailing" ? 11 : kind === "middle" || kind === "consecutive" ? 6 : 0;
  document = applyDocxOperations(document, [{ type: "insert-page-break", paragraphId: "p0", offset }]);
  if (kind === "consecutive") document = applyDocxOperations(document, [{ type: "insert-page-break", paragraphId: "p0", offset }]);
  const bytes = await exportDocx(document);
  return { document: await openDocx(bytes), bytes };
}
